/* 仿 bubble 配套插件 · 面板 v1.3.0
 * 仅在插件自己的 iframe 中生效，不向宿主注入表单样式。
 * 面板颜色在此集中调整；聊天室颜色仍由配色模块保存。
 */
:root{color-scheme:light dark;--ann-panel:#fff;--ann-ink:#242629;--ann-muted:#686c72;--ann-line:#e8e9eb;--ann-soft:#f5f6f7;--ann-accent:#282b30;--ann-button-text:#fff;--ann-danger:#ad4050}
@media(prefers-color-scheme:dark){:root{--ann-panel:#1c1d20;--ann-ink:#eeeef0;--ann-muted:#b1b4bb;--ann-line:#37393f;--ann-soft:#292b30;--ann-accent:#e9ebef;--ann-button-text:#202227;--ann-danger:#ec9aa5}}
*{box-sizing:border-box}html,body{margin:0;background:var(--ann-panel);color:var(--ann-ink);font:14px/1.55 Arial,"Noto Sans SC",Roboto,sans-serif;font-weight:400;-webkit-text-size-adjust:100%}body{overflow-wrap:anywhere}button,input,select{font-family:inherit;font-weight:400}[hidden]{display:none!important}button{cursor:pointer;min-height:40px;padding:9px 12px;border:1px solid var(--ann-line);border-radius:10px;color:var(--ann-ink);background:var(--ann-panel);font-size:13px;line-height:1.4}button:active{filter:brightness(.94)}button:disabled,input:disabled,select:disabled{opacity:.45;cursor:default}:focus-visible{outline:2px solid var(--ann-muted);outline-offset:3px}
#beauty-tabs{position:sticky;top:0;z-index:2;display:flex;gap:4px;padding:12px 16px 10px;background:var(--ann-panel);border-bottom:1px solid var(--ann-line)}#beauty-tabs button{flex:1;min-height:36px;border:0;border-radius:8px;background:transparent;color:var(--ann-muted);font-size:13px}#beauty-tabs [aria-selected=true]{background:var(--ann-soft);color:var(--ann-ink);font-weight:500}
#app,#theme-section{padding:20px 18px 12px;max-width:520px;margin:auto}h1{font-size:19px;line-height:1.4;font-weight:500;letter-spacing:0;margin:0 0 8px}.eyebrow{display:none}.who,.theme-help{font-size:13px;line-height:1.7;color:var(--ann-muted);margin:0 0 20px}label{display:block;margin:16px 0 7px;font-size:13px;font-weight:400}input[type=date],select,input[type=text]{display:block;width:100%;min-width:0;min-height:44px;border:1px solid var(--ann-line);border-radius:10px;background:var(--ann-panel);color:var(--ann-ink);padding:10px 12px;font-size:16px;line-height:1.4}input::placeholder{color:var(--ann-muted);opacity:1}.check{display:flex;gap:9px;align-items:center;margin:18px 0;font-size:13px}.check input{width:17px;height:17px;margin:0;accent-color:var(--ann-accent)}#preview{display:block;border:1px solid var(--ann-line);border-radius:12px;padding:14px;margin:18px 0;font-size:19px;font-weight:400;font-variant-numeric:tabular-nums;color:var(--ann-ink);background:var(--ann-soft)}#save,#theme-save{background:var(--ann-accent);color:var(--ann-button-text);border-color:transparent}#save{width:100%}.secondary{display:flex;gap:8px;margin-top:8px}.secondary button{flex:1;min-width:0;font-size:12px}#remove,#theme-delete-named{color:var(--ann-danger)}#notice,#theme-notice{margin:10px 0 0;font-size:12px;line-height:1.65;color:var(--ann-muted)}[data-error=true]{color:var(--ann-danger)!important}
.theme-preset{display:flex;gap:8px;margin:16px 0}.theme-preset select{flex:1;min-width:0}.theme-preset button{flex:none;font-size:12px}.theme-naming{margin:14px 0 20px;border:0;border-bottom:1px solid var(--ann-line);border-radius:0;padding:0 0 14px}.theme-naming summary{font-size:13px;color:var(--ann-muted)}.theme-naming label{margin-top:12px}.theme-naming button{margin-top:8px;width:100%;font-size:12px}#theme-delete-named:disabled{display:none}
#theme-fields>details{margin:10px 0;border:1px solid var(--ann-line);border-radius:12px;padding:0 12px}summary{padding:12px 0;font-size:13px;font-weight:500;cursor:pointer;list-style:none;display:flex;align-items:center;justify-content:space-between;gap:8px}summary::-webkit-details-marker{display:none}summary:after{content:'+';color:var(--ann-muted);font:18px/1 Arial}details[open]>summary:after{content:'−'}
.theme-field{position:relative;padding:12px 0;border-top:1px solid var(--ann-line);display:grid;grid-template-columns:minmax(0,1fr) auto;gap:8px}.theme-field label{grid-column:1/-1;margin:0;font-size:12px;color:var(--ann-muted);line-height:1.5}.theme-field>input{width:100%;min-width:0;min-height:38px;border-radius:8px;padding:7px 8px;font-size:16px}.theme-swatch{display:none}.theme-controls{display:flex;align-items:center;gap:6px}.color-trigger{width:38px;height:38px;min-height:38px;flex:none;padding:0;border:3px solid var(--ann-panel);outline:1px solid var(--ann-line);border-radius:9px}.theme-small{min-height:38px;font-size:11px;padding:6px;border:0;background:var(--ann-soft)}.theme-controls input[type=number]{width:49px;min-width:0;height:38px;padding:4px;border:1px solid var(--ann-line);border-radius:7px;background:var(--ann-panel);color:var(--ann-ink);font-size:16px}.angle-unit{font-size:12px;color:var(--ann-muted)}.theme-field:has(.angle-unit)>input{grid-column:1/-1}.theme-field:has(.angle-unit) .theme-controls{grid-column:1/-1}
.theme-actions{position:sticky;bottom:0;z-index:1;margin-top:18px;padding:10px 0 4px;background:var(--ann-panel);border-top:1px solid var(--ann-line)}.theme-save-row{display:flex;gap:8px}.theme-save-row button{flex:1;min-width:0}#theme-reset{display:block;width:100%;margin-top:6px;min-height:32px;font-size:12px;border:0;color:var(--ann-muted)}#theme-notice:empty{display:none}#beauty-signature{text-align:center;padding:14px 16px 18px;font:11px/1.5 Arial,sans-serif;letter-spacing:.5px;color:var(--ann-muted)}
/* 一个固定取色面板，适配小屏和键盘；色板本身禁止浏览器手势抢走拖动。 */
body.picking{overflow:hidden}#color-picker{position:fixed;inset:0;z-index:10;padding:12px;display:flex;align-items:center;justify-content:center;background:rgb(0 0 0 / .22);overflow:auto}.picker-card{width:100%;max-width:420px;max-height:calc(100dvh - 24px);overflow:auto;padding:14px 16px 12px;border-radius:18px;background:var(--ann-panel);box-shadow:0 12px 50px #0002}.picker-card header{display:flex;align-items:center;gap:8px;margin-bottom:12px}.picker-card header button{border:0;padding:6px 0;min-height:32px;flex:none}.picker-card h2{font-size:13px;font-weight:500;line-height:1.5;text-align:center;flex:1;margin:0}.picker-card label{font-size:12px;color:var(--ann-muted);margin:12px 0 6px}#picker-apply{font-weight:500}#picker-pad{position:relative;height:clamp(130px,34dvh,200px);border-radius:9px;touch-action:none;background-image:linear-gradient(to top,#000,transparent),linear-gradient(to right,#fff,transparent);cursor:crosshair;outline-offset:4px}#picker-dot{position:absolute;pointer-events:none;transform:translate(-50%,-50%);width:16px;height:16px;border:2px solid #fff;border-radius:50%;box-shadow:0 0 0 1px #0005}
.picker-card input[type=range]{display:block;appearance:none;-webkit-appearance:none;width:100%;height:14px;border:0;border-radius:7px;margin:8px 0 16px;touch-action:pan-y}.picker-card input[type=range]::-webkit-slider-thumb{appearance:none;width:21px;height:21px;background:#fff;border:2px solid #ddd;border-radius:50%;box-shadow:0 1px 3px #0003}#picker-hue{background:linear-gradient(to right,red,#ff0,#0f0,#0ff,#00f,#f0f,red)}#picker-alpha{background:linear-gradient(to right,transparent,var(--picked)),repeating-conic-gradient(#ddd 0% 25%,#fff 0% 50%) 0/10px 10px}.picker-alpha-label{display:flex;align-items:baseline;justify-content:space-between}.picker-alpha-label label{margin-top:4px}#picker-percent{font-size:12px;font-variant-numeric:tabular-nums;color:var(--ann-muted)}.picker-value{display:flex;align-items:center;gap:10px;margin-top:12px}.picker-value label{margin:0;flex:none}.picker-value input{min-width:0;flex:1;font-family:monospace}#picker-preview{width:34px;height:34px;border:1px solid var(--ann-line);border-radius:8px;flex:none}.picker-help{font-size:11px;text-align:center;color:var(--ann-muted);margin:10px 0 0}
html.anniversary-effects,html.anniversary-effects body{background:transparent!important;overflow:hidden}html.anniversary-effects body>*{display:none!important}

