/* 糯叽机 · 角色纪念日 v1.0.0
 * 数据：每个角色一条记录，键使用角色 ID；同名／改名不会串日期。
 * 日数：用本机年月日转换为 UTC 日序号，只比较自然日，避开夏令时的 23/25 小时。
 * 界面：chatHeaderAction / settingsTab 显示设置表单。
 * 联动：effects 仅写 --fx-anniversary-*，没有画布、粒子、动画帧或轮询。
 * 槽位识别使用 5.64 在 effects 沙箱注入的 __nuoFxEnv，不读取宿主 DOM。
 */
(function () {
  'use strict';
  var PREFIX = 'anniversary:v1:';
  var isEffects = !!window.__nuoFxEnv;
  var current = null, selected = null, known = Object.create(null), busy = false, panelLoading = false, stopped = false;
  var sequence = 0, openVersion = 0, paused = false, midnightTimer = 0, tapTimer = 0;
  var deleteArmed = '', lastPublication = '', lastRead = 0;
  function el(id) { return document.getElementById(id); }
  function pad(n) { return String(n).padStart(2, '0'); }
  function today() {
    var d = new Date();
    return String(d.getFullYear()).padStart(4, '0') + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
